4		"math"
5		"strings"
6		"testing"
7	
8		"github.com/anthnel/devdesk/internal/agentusage"
9		"github.com/anthnel/devdesk/internal/ui/datatable"
10		"github.com/anthnel/devdesk/internal/ui/testutil"
11		"github.com/anthnel/devdesk/internal/ui/theme"
12	)
13	
14	// orchestrator and subAgent build agents for the table-driven tests below.
15	func orchestrator(out int64, partial int) agentusage.Agent {
16		return agentusage.Agent{
17			Main: true, Models: []string{"model-a"}, PartialMessages: partial,
18			Tokens: agentusage.Tokens{Output: out},
19		}
20	}
21	
22	func subAgent(id, typ string, out int64, partial int) agentusage.Agent {
23		return agentusage.Agent{
24			ID: id, Type: typ, Models: []string{"model-b"}, PartialMessages: partial,
25			Tokens: agentusage.Tokens{Output: out},
26		}
27	}
