29	func TestFormatTokens(t *testing.T) {
30		tests := []struct {
31			in   int64
32			want string
33		}{
34			{0, "0"},
35			{845, "845"},
36			{999, "999"},
37			{1000, "1.0k"},
38			{1049, "1.0k"},
39			{1099, "1.0k"}, // floored, never rounded up
40			{12345, "12.3k"},
41			{99999, "99.9k"},
42			{123456, "123k"},
43			{999999, "999k"},
44			{1_000_000, "1.0M"},
45			{4_640_000, "4.6M"},
46			{1_250_000_000, "1.2B"},
47			{100_000_000, "100M"},
48			{123_456_789, "123M"},
49			{999_999_999, "999M"},
50			{123_456_789_012, "123B"},
51			{123_456_789_012_345, "123T"},
52		}
53		for _, tt := range tests {
54			if got := formatTokens(tt.in); got != tt.want {
55				t.Errorf("formatTokens(%d) = %q, want %q", tt.in, got, tt.want)
56			}
57		}
58		if got := formatTokens(math.MaxInt64); !strings.HasSuffix(got, "T") {
59			t.Errorf("formatTokens(MaxInt64) = %q, want a T suffix", got)
60		}
61	}
62	
63	// The key criterion: the floor marker belongs to partial sub-agents only.
64	func TestOutCell(t *testing.T) {
65		tests := []struct {
66			name string
67			row  agentRow
68			want string
69		}{
70			{"partial sub-agent", agentRow{Agent: subAgent("a1", "coder", 8, 1)}, "≥ 8"},
71			{"complete sub-agent", agentRow{Agent: subAgent("a1", "coder", 8, 0)}, "8"},
72			{"orchestrator never partial", agentRow{Agent: orchestrator(320, 3)}, "320"},
73			{"partial sub-agent, compact", agentRow{Agent: subAgent("a1", "coder", 12345, 2)}, "≥ 12.3k"},
74			{"zero output", agentRow{Agent: subAgent("a1", "coder", 0, 0)}, "0"},
75		}
76		for _, tt := range tests {
77			t.Run(tt.name, func(t *testing.T) {
78				if got := outCell(tt.row); got != tt.want {
79					t.Errorf("outCell = %q, want %q", got, tt.want)
80				}
81			})
82		}
83	}
84	
